import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();

async function main() {
    console.log('🌱 Seeding 38 Comprehensive Identity Roles...');

    // We'll reuse the HQ and branch tenant generated by seed.ts, or create dummy ones if missing
    const tenantHQ = await prisma.tenant.upsert({ 
        where: { slug: 'primecare-admin' }, 
        update: {}, 
        create: { name: 'PrimeCare Admin', slug: 'primecare-admin', status: 'active', allowedVpnRanges: '', corsAllowedOrigins: '', corsAllowedMethods: '', corsAllowedHeaders: '' } 
    });

    const tenantA = await prisma.tenant.upsert({ 
        where: { slug: 'prime-toronto' }, 
        update: {}, 
        create: { name: 'PrimeCare Toronto', slug: 'prime-toronto', status: 'active', allowedVpnRanges: '', corsAllowedOrigins: '', corsAllowedMethods: '', corsAllowedHeaders: '' } 
    });

    // Known static hash for 'password' used widely in PrimeCare
    const pwdHash = '240be518fabd2724ddb6f04eeb1da5967448d7e831c08c8fa822809f74c720a9';

    const definitions = [
        { role: 'ceo', email: 'ceo@primecare.com', tenant: tenantHQ.id },
        { role: 'coo', email: 'coo@primecare.com', tenant: tenantHQ.id },
        { role: 'cfo', email: 'cfo@primecare.com', tenant: tenantHQ.id },
        { role: 'cto', email: 'cto@primecare.com', tenant: tenantHQ.id },
        { role: 'compliance_manager', email: 'compliance_manager@primecare.com', tenant: tenantHQ.id },
        { role: 'head_of_bus_dev', email: 'head_of_bus_dev@primecare.com', tenant: tenantHQ.id },
        { role: 'head_of_marketing', email: 'head_of_marketing@primecare.com', tenant: tenantHQ.id },
        { role: 'training_director', email: 'training_director@primecare.com', tenant: tenantHQ.id },

        { role: 'regional_manager_ontario', email: 'regional_manager_ontario@primecare.com', tenant: tenantHQ.id },
        { role: 'regional_manager_usa', email: 'regional_manager_usa@primecare.com', tenant: tenantHQ.id },
        { role: 'franchise_sales_manager', email: 'franchise_sales_manager@primecare.com', tenant: tenantHQ.id },
        { role: 'partnership_manager', email: 'partnership_manager@primecare.com', tenant: tenantHQ.id },
        { role: 'territory_expansion_manager', email: 'territory_expansion_manager@primecare.com', tenant: tenantHQ.id },
        { role: 'general_manager', email: 'general_manager@primecare.com', tenant: tenantHQ.id },

        { role: 'franchise_owner', email: 'franchise_owner@primecare.com', tenant: tenantA.id },
        { role: 'operations_manager', email: 'operations_manager@primecare.com', tenant: tenantA.id },
        { role: 'scheduler', email: 'scheduler@primecare.com', tenant: tenantA.id },
        { role: 'billing_admin', email: 'billing_admin@primecare.com', tenant: tenantA.id },
        { role: 'hr_manager', email: 'hr_manager@primecare.com', tenant: tenantA.id },

        { role: 'rn', email: 'rn@primecare.com', tenant: tenantA.id },
        { role: 'rpn', email: 'rpn@primecare.com', tenant: tenantA.id },
        { role: 'rmt', email: 'rmt@primecare.com', tenant: tenantA.id },
        { role: 'psw', email: 'psw@primecare.com', tenant: tenantA.id },
        { role: 'physiotherapist', email: 'physiotherapist@primecare.com', tenant: tenantA.id },
        { role: 'chiropractor', email: 'chiropractor@primecare.com', tenant: tenantA.id },
        { role: 'occupational_therapist', email: 'occupational_therapist@primecare.com', tenant: tenantA.id },
        { role: 'speech_pathologist', email: 'speech_pathologist@primecare.com', tenant: tenantA.id },

        { role: 'customer_support', email: 'customer_support@primecare.com', tenant: tenantA.id },
        { role: 'intake_coordinator', email: 'intake_coordinator@primecare.com', tenant: tenantA.id },
        { role: 'quality_assurance', email: 'quality_assurance@primecare.com', tenant: tenantHQ.id },
        { role: 'training_coordinator', email: 'training_coordinator@primecare.com', tenant: tenantHQ.id },

        { role: 'local_marketing', email: 'local_marketing@primecare.com', tenant: tenantA.id },
        { role: 'community_outreach', email: 'community_outreach@primecare.com', tenant: tenantA.id },
        { role: 'territory_sales', email: 'territory_sales@primecare.com', tenant: tenantA.id },

        { role: 'client', email: 'client@primecare.com', tenant: tenantA.id },
        { role: 'family_member', email: 'family_member@primecare.com', tenant: tenantA.id },

        { role: 'admin', email: 'admin@primecare.com', tenant: tenantHQ.id },
        { role: 'receptionist', email: 'receptionist@primecare.com', tenant: tenantA.id }
    ];

    let inserted = 0;
    for (const d of definitions) {
        await prisma.user.upsert({
            where: { email: d.email },
            update: {
                roles: d.role,
                status: 'active'
            },
            create: {
                email: d.email,
                passwordHash: pwdHash,
                roles: d.role,
                tenantId: d.tenant,
                status: 'active'
            }
        });
        inserted++;
    }

    console.log(`✅ Upserted ${inserted} robust roles into DB!`);
}

main()
    .catch(console.error)
    .finally(() => prisma.$disconnect());
